        if (ownerFieldsDto != null) {
            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
        }
        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
